import * as fs from 'fs';
import * as readline from 'readline';

async function parseJsonl(inputPath: string, outputPath: string) {
    const fileStream = fs.createReadStream(inputPath);
    const rl = readline.createInterface({
        input: fileStream,
        crlfDelay: Infinity
    });

    const outputStream = fs.createWriteStream(outputPath);

    outputStream.write('# JSONL Data Export\n\n');

    for await (const line of rl) {
        if (!line.trim()) continue;
        try {
            const data = JSON.parse(line);
            outputStream.write(`## Entry ${data.id || 'N/A'}\n`);

            for (const [key, value] of Object.entries(data)) {
                if (key === 'message') {
                    outputStream.write(`**${key}**: \n${value}\n\n`);
                } else if (typeof value === 'object' && value !== null) {
                    outputStream.write(`**${key}**: \n\`\`\`json\n${JSON.stringify(value, null, 2)}\n\`\`\`\n\n`);
                } else {
                    outputStream.write(`**${key}**: ${value}\n\n`);
                }
            }
            outputStream.write('--- \n\n');
        } catch (err) {
            console.error(`Error parsing line: ${line}`, err);
        }
    }

    console.log(`Finished processing. Output saved to ${outputPath}`);
}

const inputPath = 'input.jsonl';
const outputPath = 'output.md';

parseJsonl(inputPath, outputPath);

